  "result": "[{\"post_id\": \"post_registration_2026\", \"account_id\": \"acct_pharm_exam\", \"title\": \"关于做好 2026 年度执业药师职业资格考试报名工作的通知\", \"summary\": \"报名时间为 8 月 5 日至 8 月 28 日。报考西药类（药学类）须具备药学、中药学或相关专业学历，并达到相应工作年限；报名须提交学历证书、工作年限证明、近期证件照与报考承诺书。工作年限计算截止 2026 年 12 月 31 日。\", \"url\": \"https://notice.pharm-exam.example.test/posts/post_registration_2026\", \"published_at\": \"2026-08-03T09:00:00+08:00\"}, {\"post_id\": \"post_pharm_exam_205\", \"account_id\": \"acct_pharm_exam\", \"title\": \"关于开展合理用药宣传月活动的通知（第 11 批）\", \"summary\": \"活动期间将在 108 个社区开展用药咨询义诊，欢迎执业药师报名参与志愿服务。\", \"url\": \"https://notice.pharm-exam.example.test/posts/post_pharm_exam_205\", \"published_at\": \"2026-08-01T19:00:00+08:00\"}, {\"post_id\": \"post_pharm_exam_202\", \"account_id\": \"acct_pharm_exam\", \"title\": \"中药饮片经营专项培训通知（第 11 批）\", \"summary\": \"培训内容包括饮片真伪鉴别、储存养护与处方调剂，计划开设 20 期，每期 557 人。\", \"url\": \"https://notice.pharm-exam.example.test/posts/post_pharm_exam_202\", \"published_at\": \"2026-08-01T16:00:00+08:00\"}, {\"post_id\": \"post_pharm_exam_201\", \"account_id\": \"acct_pharm_exam\", \"title\": \"关于医保定点药店药品追溯的工作提示（第 11 批）\", \"summary\": \"2月起，医保定点药店销售的追溯品种须扫码上传，未上传的暂缓结算。\", \"url\": \"https://notice.pharm-exam.example.test/posts/post_pharm_exam_201\", \"published_at\": \"2026-08-01T15:00:00+08:00\"}, {\"post_id\": \"post_pharm_exam_197\", \"account_id\": \"acct_pharm_exam\", \"title\": \"关于加强特殊管理药品管理的提示（第 11 批）\", \"summary\": \"11月排查发现麻醉药品专用处方保存不规范 71 家，均已整改到位。\", \"url\": \"https://notice.pharm-exam.example.test/posts/post_pharm_exam_197\", \"published_at\": \"2026-08-01T10:00:00+08:00\"}, {\"post_id\": \"post_pharm_exam_196\", \"account_id\": \"acct_pharm_exam\", \"title\": \"基本药物配备使用情况调度（第 11 批）\", \"summary\": \"全省零售药店基本药物配备品规数中位数为 481 个，较上季度增加 76 个。\", \"url\": \"https://notice.pharm-exam.example.test/posts/post_pharm_exam_196\", \"published_at\": \"2026-08-01T05:00:00+08:00\"}, {\"post_id\": \"post_pharm_exam_190\", \"account_id\": \"acct_pharm_exam\", \"title\": \"关于开展合理用药宣传月活动的通知（第 10 批）\", \"summary\": \"活动期间将在 161 个社区开展用药咨询义诊，欢迎执业药师报名参与志愿服务。\", \"url\": \"https://notice.pharm-exam.example.test/posts/post_pharm_exam_190\", \"published_at\": \"2026-07-31T23:00:00+08:00\"}, {\"post_id\": \"post_pharm_exam_188\", \"account_id\": \"acct_pharm_exam\", \"title\": \"关于药品冷链管理的检查情况（第 10 批）\", \"summary\": \"抽查冷链品种经营企业 445 家，温度记录不完整 61 家，已要求限期整改。\", \"url\": \"https://notice.pharm-exam.example.test/posts/post_pharm_exam_188\", \"published_at\": \"2026-07-31T15:00:00+08:00\"}, {\"post_id\": \"post_pharm_exam_187\", \"account_id\": \"acct_pharm_exam\", \"title\": \"中药饮片经营专项培训通知（第 10 批）\", \"summary\": \"培训内容包括饮片真伪鉴别、储存养护与处方调剂，计划开设 49 期，每期 859 人。\", \"url\": \"https://notice.pharm-exam.example.test/posts/post_pharm_exam_187\", \"published_at\": \"2026-07-31T14:00:00+08:00\"}, {\"post_id\": \"post_pharm_exam_182\", \"account_id\": \"acct_pharm_exam\", \"title\": \"关于加强特殊管理药品管理的提示（第 10 批）\", \"summary\": \"3月排查发现麻醉药品专用处方保存不规范 62 家，均已整改到位。\", \"url\": \"https://notice.pharm-exam.example.test/posts/post_pharm_exam_182\", \"published_at\": \"2026-07-31T08:00:00+08:00\"}, {\"post_id\": \"post_pharm_exam_180\", \"account_id\": \"acct_pharm_exam\", \"title\": \"关于11月药品抽检结果的公示\", \"summary\": \"共抽检 373 批次，合格 6 批次，不合格品种及企业名单见附件。\", \"url\": \"https://notice.pharm-exam.example.test/posts/post_pharm_exam_180\", \"published_at\": \"2026-07-31T03:00:00+08:00\"}, {\"post_id\": \"post_pharm_exam_178\", \"account_id\": \"acct_pharm_exam\", \"title\": \"关于1月份药品价格监测情况的通报\", \"summary\": \"监测品种 343 个，其中价格上涨 6 个、下降 70 个，整体波动幅度在合理区间。\", \"url\": \"https://notice.pharm-exam.example.test/posts/post_pharm_exam_178\", \"published_at\": \"2026-07-31T02:00:00+08:00\"}, {\"post_id\": \"post_pharm_exam_177\", \"account_id\": \"acct_pharm_exam\", \"title\": \"零售终端用药咨询能力提升培训回顾（第 10 批）\", \"summary\": \"本期培训覆盖慢病用药、儿童剂量换算与老年人多重用药，参训 550 人，考核合格率 71%。\", \"url\": \"https://notice.pharm-exam.example.test/posts/post_pharm_exam_177\", \"published_at\": \"2026-07-31T01:00:00+08:00