  "result": "[{\"post_id\": \"post_law_update_2026\", \"account_id\": \"acct_pharm_exam\", \"title\": \"2026 年度药事管理与法规科目考试内容调整公告\", \"summary\": \"根据法规修订情况，REG_GSP_IMPL_2016 已于 2026 年 1 月废止，相关内容不再列入考试范围；新增 REG_DRUG_TRACE_2026 药品追溯管理与 REG_RX_FLOW_2026 处方流转管理两项内容，考生复习时请以最新大纲为准。\", \"url\": \"https://notice.pharm-exam.example.test/posts/post_law_update_2026\", \"published_at\": \"2026-08-24T10:20:00+08:00\"}, {\"post_id\": \"post_registration_2026\", \"account_id\": \"acct_pharm_exam\", \"title\": \"关于做好 2026 年度执业药师职业资格考试报名工作的通知\", \"summary\": \"报名时间为 8 月 5 日至 8 月 28 日。报考西药类（药学类）须具备药学、中药学或相关专业学历，并达到相应工作年限；报名须提交学历证书、工作年限证明、近期证件照与报考承诺书。工作年限计算截止 2026 年 12 月 31 日。\", \"url\": \"https://notice.pharm-exam.example.test/posts/post_registration_2026\", \"published_at\": \"2026-08-03T09:00:00+08:00\"}, {\"post_id\": \"post_pharm_exam_205\", \"account_id\": \"acct_pharm_exam\", \"title\": \"关于开展合理用药宣传月活动的通知（第 11 批）\", \"summary\": \"活动期间将在 108 个社区开展用药咨询义诊，欢迎执业药师报名参与志愿服务。\", \"url\": \"https://notice.pharm-exam.example.test/posts/post_pharm_exam_205\", \"published_at\": \"2026-08-01T19:00:00+08:00\"}, {\"post_id\": \"post_pharm_exam_202\", \"account_id\": \"acct_pharm_exam\", \"title\": \"中药饮片经营专项培训通知（第 11 批）\", \"summary\": \"培训内容包括饮片真伪鉴别、储存养护与处方调剂，计划开设 20 期，每期 557 人。\", \"url\": \"https://notice.pharm-exam.example.test/posts/post_pharm_exam_202\", \"published_at\": \"2026-08-01T16:00:00+08:00\"}, {\"post_id\": \"post_pharm_exam_201\", \"account_id\": \"acct_pharm_exam\", \"title\": \"关于医保定点药店药品追溯的工作提示（第 11 批）\", \"summary\": \"2月起，医保定点药店销售的追溯品种须扫码上传，未上传的暂缓结算。\", \"url\": \"https://notice.pharm-exam.example.test/posts/post_pharm_exam_201\", \"published_at\": \"2026-08-01T15:00:00+08:00\"}, {\"post_id\": \"post_pharm_exam_197\", \"account_id\": \"acct_pharm_exam\", \"title\": \"关于加强特殊管理药品管理的提示（第 11 批）\", \"summary\": \"11月排查发现麻醉药品专用处方保存不规范 71 家，均已整改到位。\", \"url\": \"https://notice.pharm-exam.example.test/posts/post_pharm_exam_197\", \"published_at\": \"2026-08-01T10:00:00+08:00\"